    "--create": "CREATE TABLE session_events_enriched (user_id STRING, event_data STRING, enriched_data STRING) WITH (\"connector\" = 'kafka', \"topic\" = 'session-events-enriched', \"properties.bootstrap.servers\" = 'kafka:9092', \"properties.group.id\" = 'flink-session-group', \"format\" = 'json')",
