# Kafka Configuration

## Kafka Topics

```bash
# Create Kafka topics
kafka-topics --bootstrap-server kafka:9092 --create --topic vehicle-positions --partitions 3 --replication-factor 3 --config retention.ms=600000
kafka-topics --bootstrap-server kafka:9092 --create --topic vehicle-positions-clean --partitions 3 --replication-factor 3 --config retention.ms=600000
```

## Flink Configuration

```properties
# Flink Configuration
state.checkpoint.dir=/flink-state/checkpoints
state.checkpoint.config.s3://flink-state/checkpoints.compression=true
state.checkpoint.config.s3://flink-state/checkpoints.max-retained-bytes=104857600
state.checkpoint.config.s3://flink-state/checkpoints.max-retained-checkpoints=10
jobmanager.rpc.netty.port=8081
jobmanager.rpc.discovery.listener.port=8082
jobmanager.rpc.discovery.listener.host=jobmanager
parallelism.default=8
```

## SQL Configuration

```sql
-- SQL Configuration
CREATE TABLE vehicle_positions (
    vehicle_id VARCHAR,
    position_time TIMESTAMP,
    latitude DOUBLE,
    longitude DOUBLE
) WITH (
    'connector' = 'kafka',
    'topic' = 'vehicle-positions',
    'properties.bootstrap.servers' = 'kafka:9092',
    'properties.group.id' = 'flink-vehicle-positions-group'
);

CREATE TABLE vehicle_positions_clean (
    vehicle_id VARCHAR,
    position_time TIMESTAMP,
    latitude DOUBLE,
    longitude DOUBLE
) WITH (
    'connector' = 'kafka',
    'topic' = 'vehicle-positions-clean',
    'properties.bootstrap.servers' = 'kafka:9092',
    'properties.group.id' = 'flink-vehicle-positions-clean-group'
);
```

## Execution Configuration

```properties
# Execution Configuration
execution.checkpointing.interval=10000
txn_timeout=1000
eos_latency=100
```

## Flink Job Configuration

```java
// Flink Job Configuration
public class FlinkJob {
    public static void main(String[] args) throws Exception {
        final StreamExecutionEnvironment env = StreamExecutionEnvironment.getExecutionEnvironment();
        env.setStreamTimeCharacteristic(TimeCharacteristic.EventTime);
        env.getConfig().setAutoOffsetReset(AutoOffsetReset.EARLIEST);
        env.getConfig().setMaxParallelism(8);

        // Source
        DataStream<VehiclePosition> vehiclePositions = env
                .addSource(new KafkaSource<>(
                        new Properties(),
                        new ConsumerConfig("topic", "vehicle-positions")
                ))
                .map(VehiclePosition::new);

        // Sink
        vehiclePositions.addSink(new KafkaSink<>(
                new Properties(),
                new ConsumerConfig("topic", "vehicle-positions-clean")
        ));

        env.execute("Flink Job for Vehicle Positions");
    }
}
```

